import { BaseGameScene } from './BaseGameScene';
import { GameObjects } from 'phaser';

export class ColorsScene extends BaseGameScene {
  private colors = [
    { name: 'Red', hex: 0xff6b6b, emoji: '🍎' },
    { name: 'Blue', hex: 0x4ecdc4, emoji: '💙' },
    { name: 'Yellow', hex: 0xffe66d, emoji: '🌞' },
    { name: 'Green', hex: 0xa8e6cf, emoji: '🌿' },
    { name: 'Pink', hex: 0xff8b94, emoji: '🌸' },
    { name: 'Purple', hex: 0xb8b8ff, emoji: '🍇' },
    { name: 'Orange', hex: 0xffa07a, emoji: '🍊' },
    { name: 'Brown', hex: 0x8b4513, emoji: '🍫' }
  ];
  
  private currentColorIndex: number = 0;
  private colorDisplay!: GameObjects.Text;
  private paletteContainer!: GameObjects.Container;
  private isAnimating: boolean = false;

  constructor() {
    super({ key: 'ColorsScene' });
  }

  create(): void {
    super.create();
    this.totalSteps = this.colors.length;
    this.shuffleColors();
    this.createColorDisplay();
    this.createPalette();
    this.showCurrentColor();
  }

  private shuffleColors(): void {
    for (let i = this.colors.length - 1; i > 0; i--) {
      const j = Phaser.Math.Between(0, i);
      [this.colors[i], this.colors[j]] = [this.colors[j], this.colors[i]];
    }
  }

  private createColorDisplay(): void {
    const centerX = this.scale.width / 2;
    
    this.add.text(centerX, 100, 'Find the matching color!', {
      fontFamily: 'Arial, Helvetica, sans-serif',
      fontSize: '24px',
      color: '#718096'
    }).setOrigin(0.5);
    
    this.colorDisplay = this.add.text(centerX, 180, '', {
      fontFamily: 'Arial, Helvetica, sans-serif',
      fontSize: '48px',
      fontWeight: 'bold',
      color: '#2d3748'
    }).setOrigin(0.5);
  }

  private createPalette(): void {
    this.paletteContainer = this.add.container(this.scale.width / 2, this.scale.height / 2 + 80);
    
    this.colors.forEach((color, index) => {
      const col = index % 4;
      const row = Math.floor(index / 4);
      const spacing = 120;
      const x = (col - 1.5) * spacing;
      const y = (row - 0.5) * spacing;
      
      this.createColorButton(color, x, y, index);
    });
  }

  private createColorButton(color: any, x: number, y: number, index: number): void {
    const container = this.add.container(x, y);
    
    const bg = this.add.graphics();
    bg.fillStyle(color.hex, 1);
    bg.fillCircle(0, 0, 50);
    bg.lineStyle(4, 0xffffff, 1);
    bg.strokeCircle(0, 0, 50);
    
    const emoji = this.add.text(0, 0, color.emoji, {
      fontSize: '40px'
    }).setOrigin(0.5);
    
    container.add([bg, emoji]);
    container.setData('color', color);
    container.setData('index', index);
    
    const hitArea = new Phaser.Geom.Circle(0, 0, 50);
    container.setInteractive(hitArea, Phaser.Geom.Circle.Contains);
    
    container.on('pointerdown', () => this.onColorTap(container));
    
    container.on('pointerover', () => {
      this.tweens.add({
        targets: container,
        scale: 1.1,
        duration: 100
      });
    });
    
    container.on('pointerout', () => {
      this.tweens.add({
        targets: container,
        scale: 1,
        duration: 100
      });
    });
    
    this.paletteContainer.add(container);
    
    container.setScale(0);
    this.tweens.add({
      targets: container,
      scale: { from: 0, to: 1 },
      duration: 300,
      delay: index * 80,
      ease: 'Back.out'
    });
  }

  private showCurrentColor(): void {
    const color = this.colors[this.currentColorIndex];
    this.colorDisplay.setText(`${color.emoji} ${color.name}`);
    this.colorDisplay.setColor('#' + color.hex.toString(16).padStart(6, '0'));
  }

  private onColorTap(container: GameObjects.Container): void {
    if (this.isAnimating) return;
    
    const color = container.getData('color');
    const targetColor = this.colors[this.currentColorIndex];
    
    if (color.name === targetColor.name) {
      this.isAnimating = true;
      this.playSuccessSound();
      this.showCelebration(container.x + this.paletteContainer.x, container.y + this.paletteContainer.y);
      
      this.tweens.add({
        targets: container,
        scale: { from: 1, to: 1.5 },
        duration: 300,
        yoyo: true,
        onComplete: () => {
          this.currentColorIndex++;
          this.incrementProgress();
          
          if (this.currentColorIndex >= this.colors.length) {
            this.onGameComplete();
          } else {
            this.showCurrentColor();
            this.isAnimating = false;
          }
        }
      });
    } else {
      this.playWrongSound();
      this.tweens.add({
        targets: container,
        x: { from: container.x, to: container.x - 15 },
        yoyo: true,
        repeat: 3,
        duration: 80
      });
    }
  }

  private onGameComplete(): void {
    this.playSuccessSound();
    this.showCelebration(this.scale.width / 2, this.scale.height / 2);
    
    this.time.delayedCall(1500, () => {
      this.createSpeechBubble(this.scale.width / 2, 200, 'Amazing! You know all the colors! 🌈');
    });
    
    this.time.delayedCall(3000, () => {
      this.scene.start('MenuScene');
    });
  }
}