import { Scene, GameObjects, Input } from 'phaser';

export class BaseGameScene extends Scene {
  protected backButton!: GameObjects.Container;
  protected homeButton!: GameObjects.Container;
  protected progressBar!: GameObjects.Graphics;
  protected currentProgress: number = 0;
  protected totalSteps: number = 0;

  constructor(key: string) {
    super({ key });
  }

  create(): void {
    this.createBackground();
    this.createNavigation();
    this.createProgressBar();
    this.setupInputs();
  }

  protected createBackground(): void {
    const graphics = this.add.graphics();
    const width = this.scale.width;
    const height = this.scale.height;
    
    graphics.fillGradientStyle(0xf8fafc, 0xf8fafc, 0xe2e8f0, 0xe2e8f0, 1);
    graphics.fillRect(0, 0, width, height);
    
    graphics.generateTexture(`bg_${this.scene.key}`, width, height);
    graphics.destroy();
    
    this.add.image(0, 0, `bg_${this.scene.key}`).setOrigin(0);
  }

  protected createNavigation(): void {
    const padding = 20;
    const buttonSize = 60;
    
    this.backButton = this.createNavButton(
      padding + buttonSize/2,
      padding + buttonSize/2,
      '←',
      () => this.scene.start('MenuScene'),
      0xe2e8f0
    );
    
    this.homeButton = this.createNavButton(
      this.scale.width - padding - buttonSize/2,
      padding + buttonSize/2,
      '🏠',
      () => this.scene.start('MenuScene'),
      0x667eea
    );
  }

  protected createNavButton(
    x: number, 
    y: number, 
    text: string, 
    callback: () => void, 
    bgColor: number
  ): GameObjects.Container {
    const container = this.add.container(x, y);
    
    const bg = this.add.graphics();
    bg.fillStyle(bgColor, 1);
    bg.fillCircle(0, 0, 30);
    bg.lineStyle(2, 0xffffff, 0.5);
    bg.strokeCircle(0, 0, 30);
    
    const label = this.add.text(0, 0, text, {
      fontFamily: 'Arial, Helvetica, sans-serif',
      fontSize: '24px',
      color: '#ffffff'
    }).setOrigin(0.5);
    
    container.add([bg, label]);
    
    const hitArea = new Phaser.Geom.Circle(0, 0, 30);
    container.setInteractive(hitArea, Phaser.Geom.Circle.Contains);
    
    container.on('pointerdown', () => {
      this.sound.play('click', { volume: 0.3 });
      this.tweens.add({
        targets: container,
        scaleX: 0.9,
        scaleY: 0.9,
        duration: 100,
        yoyo: true,
        onComplete: callback
      });
    });
    
    return container;
  }

  protected createProgressBar(): void {
    this.progressBar = this.add.graphics();
    this.updateProgressBar();
  }

  protected updateProgressBar(): void {
    const barWidth = this.scale.width - 160;
    const barHeight = 8;
    const x = 80;
    const y = 50;
    
    this.progressBar.clear();
    
    this.progressBar.fillStyle(0xe2e8f0, 1);
    this.progressBar.fillRoundedRect(x, y, barWidth, barHeight, 4);
    
    if (this.totalSteps > 0) {
      const progressWidth = (this.currentProgress / this.totalSteps) * barWidth;
      this.progressBar.fillStyle(0x667eea, 1);
      this.progressBar.fillRoundedRect(x, y, progressWidth, barHeight, 4);
    }
  }

  protected incrementProgress(): void {
    this.currentProgress++;
    this.updateProgressBar();
  }

  protected setupInputs(): void {
    this.input.keyboard?.on('keydown-ESC', () => {
      this.scene.start('MenuScene');
    });
  }

  protected playSuccessSound(): void {
    this.sound.play('success', { volume: 0.4 });
  }

  protected playPopSound(): void {
    this.sound.play('pop', { volume: 0.4 });
  }

  protected playWrongSound(): void {
    this.sound.play('wrong', { volume: 0.3 });
  }

  protected showCelebration(x: number, y: number): void {
    const colors = [0xff6b6b, 0x4ecdc4, 0xffe66d, 0xa8e6cf, 0xff8b94, 0xb8b8ff];
    
    for (let i = 0; i < 12; i++) {
      const angle = (i / 12) * Math.PI * 2;
      const distance = Phaser.Math.Between(50, 150);
      const targetX = x + Math.cos(angle) * distance;
      const targetY = y + Math.sin(angle) * distance;
      const color = Phaser.Utils.Array.GetRandom(colors);
      const size = Phaser.Math.Between(10, 25);
      
      const particle = this.add.graphics();
      particle.fillStyle(color, 1);
      particle.fillCircle(0, 0, size);
      particle.x = x;
      particle.y = y;
      
      this.tweens.add({
        targets: particle,
        x: targetX,
        y: targetY,
        alpha: { from: 1, to: 0 },
        scale: { from: 1, to: 0.3 },
        duration: Phaser.Math.Between(800, 1200),
        ease: 'Cubic.out',
        onComplete: () => particle.destroy()
      });
    }
  }

  protected createSpeechBubble(x: number, y: number, text: string): GameObjects.Container {
    const container = this.add.container(x, y);
    
    const bubble = this.add.graphics();
    bubble.fillStyle(0xffffff, 1);
    bubble.lineStyle(2, 0x667eea, 1);
    bubble.fillRoundedRect(-80, -40, 160, 50, 15);
    bubble.fillTriangle(-10, 10, 0, 25, 10, 10);
    
    const label = this.add.text(0, -15, text, {
      fontFamily: 'Arial, Helvetica, sans-serif',
      fontSize: '18px',
      fontWeight: 'bold',
      color: '#2d3748'
    }).setOrigin(0.5);
    
    container.add([bubble, label]);
    container.setScale(0);
    
    this.tweens.add({
      targets: container,
      scale: { from: 0, to: 1 },
      duration: 300,
      ease: 'Back.out'
    });
    
    return container;
  }
}