import { BaseGameScene } from './BaseGameScene';
import { GameObjects } from 'phaser';

interface Card {
  container: GameObjects.Container;
  value: string;
  matched: boolean;
  flipped: boolean;
}

export class MemoryScene extends BaseGameScene {
  private cardValues = ['🍎', '🍌', '🍇', '🍊', '🍓', '🥝', '🍍', '🥭'];
  private cards: Card[] = [];
  private firstFlipped: Card | null = null;
  private secondFlipped: Card | null = null;
  private matchedPairs: number = 0;
  private totalPairs: number = 8;
  private canFlip: boolean = true;
  private gridCols: number = 4;
  private gridRows: number = 4;

  constructor() {
    super({ key: 'MemoryScene' });
  }

  create(): void {
    super.create();
    this.totalSteps = this.totalPairs;
    this.createInstructions();
    this.createBoard();
  }

  private createInstructions(): void {
    const centerX = this.scale.width / 2;
    
    this.add.text(centerX, 80, 'Find matching pairs!', {
      fontFamily: 'Arial, Helvetica, sans-serif',
      fontSize: '28px',
      fontWeight: 'bold',
      color: '#667eea'
    }).setOrigin(0.5);
    
    this.add.text(centerX, 115, 'Tap cards to flip them', {
      fontFamily: 'Arial, Helvetica, sans-serif',
      fontSize: '18px',
      color: '#718096'
    }).setOrigin(0.5);
  }

  private createBoard(): void {
    const centerX = this.scale.width / 2;
    const centerY = this.scale.height / 2 + 20;
    const cardSize = 100;
    const gap = 15;
    
    const boardWidth = this.gridCols * cardSize + (this.gridCols - 1) * gap;
    const boardHeight = this.gridRows * cardSize + (this.gridRows - 1) * gap;
    const startX = centerX - boardWidth / 2 + cardSize / 2;
    const startY = centerY - boardHeight / 2 + cardSize / 2;
    
    const values = [...this.cardValues, ...this.cardValues];
    for (let i = values.length - 1; i > 0; i--) {
      const j = Phaser.Math.Between(0, i);
      [values[i], values[j]] = [values[j], values[i]];
    }
    
    values.forEach((value, index) => {
      const col = index % this.gridCols;
      const row = Math.floor(index / this.gridCols);
      const x = startX + col * (cardSize + gap);
      const y = startY + row * (cardSize + gap);
      
      this.createCard(x, y, cardSize, value, index);
    });
  }

  private createCard(x: number, y: number, size: number, value: string, index: number): void {
    const container = this.add.container(x, y);
    
    const back = this.add.graphics();
    back.fillStyle(0x667eea, 1);
    back.fillRoundedRect(-size/2, -size/2, size, size, 12);
    back.lineStyle(3, 0x764ba2, 1);
    back.strokeRoundedRect(-size/2, -size/2, size, size, 12);
    
    const pattern = this.add.graphics();
    pattern.fillStyle(0x764ba2, 0.3);
    for (let i = -1; i <= 1; i++) {
      for (let j = -1; j <= 1; j++) {
        pattern.fillCircle(i * 30, j * 30, 8);
      }
    }
    
    const front = this.add.graphics();
    front.fillStyle(0xffffff, 1);
    front.fillRoundedRect(-size/2, -size/2, size, size, 12);
    front.lineStyle(3, 0x667eea, 1);
    front.strokeRoundedRect(-size/2, -size/2, size, size, 12);
    
    const valueText = this.add.text(0, 0, value, {
      fontSize: '48px'
    }).setOrigin(0.5);
    
    container.add([back, pattern, front, valueText]);
    front.setVisible(false);
    valueText.setVisible(false);
    
    container.setData('card', {
      container,
      value,
      matched: false,
      flipped: false,
      back,
      pattern,
      front,
      valueText
    });
    
    const hitArea = new Phaser.Geom.Rectangle(-size/2, -size/2, size, size);
    container.setInteractive(hitArea, Phaser.Geom.Rectangle.Contains);
    
    container.on('pointerdown', () => this.onCardTap(container));
    
    this.cards.push(container.getData('card'));
    
    container.setScale(0);
    this.tweens.add({
      targets: container,
      scale: { from: 0, to: 1 },
      duration: 300,
      delay: index * 50,
      ease: 'Back.out'
    });
  }

  private onCardTap(container: GameObjects.Container): void {
    if (!this.canFlip) return;
    
    const card = container.getData('card');
    if (card.matched || card.flipped) return;
    
    this.flipCard(card, true);
    
    if (!this.firstFlipped) {
      this.firstFlipped = card;
    } else if (!this.secondFlipped) {
      this.secondFlipped = card;
      this.canFlip = false;
      this.time.delayedCall(800, () => this.checkMatch());
    }
  }

  private flipCard(card: Card, show: boolean): void {
    card.flipped = show;
    
    const scaleX = show ? 0 : 1;
    const targetScaleX = show ? 1 : 0;
    
    this.tweens.add({
      targets: [card.back, card.pattern, card.container],
      scaleX: { from: 1, to: 0 },
      duration: 200,
      ease: 'Power2',
      onComplete: () => {
        card.back.setVisible(!show);
        card.pattern.setVisible(!show);
        card.front.setVisible(show);
        card.valueText.setVisible(show);
        
        this.tweens.add({
          targets: [card.front, card.valueText, card.container],
          scaleX: { from: 0, to: 1 },
          duration: 200,
          ease: 'Power2'
        });
      }
    });
    
    if (show) {
      this.playClickSound();
    }
  }

  private checkMatch(): void {
    if (this.firstFlipped!.value === this.secondFlipped!.value) {
      this.onMatch();
    } else {
      this.onMismatch();
    }
  }

  private onMatch(): void {
    this.firstFlipped!.matched = true;
    this.secondFlipped!.matched = true;
    this.matchedPairs++;
    this.incrementProgress();
    
    this.playSuccessSound();
    this.showCelebration(
      this.firstFlipped!.container.x,
      this.firstFlipped!.container.y
    );
    this.showCelebration(
      this.secondFlipped!.container.x,
      this.secondFlipped!.container.y
    );
    
    this.tweens.add({
      targets: [this.firstFlipped!.container, this.secondFlipped!.container],
      scale: { from: 1, to: 1.2 },
      duration: 300,
      yoyo: true,
      onComplete: () => {
        this.firstFlipped = null;
        this.secondFlipped = null;
        this.canFlip = true;
        
        if (this.matchedPairs >= this.totalPairs) {
          this.onGameComplete();
        }
      }
    });
  }

  private onMismatch(): void {
    this.playWrongSound();
    
    this.flipCard(this.firstFlipped!, false);
    this.flipCard(this.secondFlipped!, false);
    
    this.time.delayedCall(400, () => {
      this.firstFlipped = null;
      this.secondFlipped = null;
      this.canFlip = true;
    });
  }

  private onGameComplete(): void {
    this.playSuccessSound();
    this.showCelebration(this.scale.width / 2, this.scale.height / 2);
    
    this.time.delayedCall(1500, () => {
      this.createSpeechBubble(this.scale.width / 2, 200, 'Excellent memory! You found all pairs! 🧠✨');
    });
    
    this.time.delayedCall(3000, () => {
      this.scene.start('MenuScene');
    });
  }
}