import { Game } from 'phaser';
import { GameConfig } from './gameConfig';
import { BootScene } from './scenes/BootScene';
import { MenuScene } from './scenes/MenuScene';
import { CountingScene } from './scenes/CountingScene';
import { ColorsScene } from './scenes/ColorsScene';
import { ShapesScene } from './scenes/ShapesScene';
import { AnimalsScene } from './scenes/AnimalsScene';
import { BalloonsScene } from './scenes/BalloonsScene';
import { MemoryScene } from './scenes/MemoryScene';

const config: Phaser.Types.Core.GameConfig = {
  ...GameConfig,
  scene: [
    BootScene,
    MenuScene,
    CountingScene,
    ColorsScene,
    ShapesScene,
    AnimalsScene,
    BalloonsScene,
    MemoryScene
  ],
  callbacks: {
    postBoot: () => {
      const loading = document.getElementById('loading');
      if (loading) {
        loading.classList.add('hidden');
        setTimeout(() => loading.remove(), 500);
      }
    }
  }
};

const game = new Game(config);

(window as any).game = game;