import { BaseGameScene } from './BaseGameScene';
import { GameObjects } from 'phaser';

export class AnimalsScene extends BaseGameScene {
  private animals = [
    { key: 'cow', name: 'Cow', sound: 'Moo!', emoji: '🐄', color: 0x8b4513 },
    { key: 'pig', name: 'Pig', sound: 'Oink!', emoji: '🐷', color: 0xffb6c1 },
    { key: 'chicken', name: 'Chicken', sound: 'Cluck!', emoji: '🐔', color: 0xffd700 },
    { key: 'sheep', name: 'Sheep', sound: 'Baa!', emoji: '🐑', color: 0xf5f5dc },
    { key: 'horse', name: 'Horse', sound: 'Neigh!', emoji: '🐴', color: 0x8b4513 },
    { key: 'duck', name: 'Duck', sound: 'Quack!', emoji: '🦆', color: 0xffff00 },
    { key: 'cat', name: 'Cat', sound: 'Meow!', emoji: '🐱', color: 0xff6b6b },
    { key: 'dog', name: 'Dog', sound: 'Woof!', emoji: '🐶', color: 0x4ecdc4 }
  ];
  
  private currentIndex: number = 0;
  private animalContainer!: GameObjects.Container;
  private isAnimating: boolean = false;

  constructor() {
    super({ key: 'AnimalsScene' });
  }

  create(): void {
    super.create();
    this.totalSteps = this.animals.length;
    this.shuffleAnimals();
    this.createAnimalDisplay();
    this.showAnimal(this.currentIndex);
  }

  private shuffleAnimals(): void {
    for (let i = this.animals.length - 1; i > 0; i--) {
      const j = Phaser.Math.Between(0, i);
      [this.animals[i], this.animals[j]] = [this.animals[j], this.animals[i]];
    }
  }

  private createAnimalDisplay(): void {
    const centerX = this.scale.width / 2;
    const centerY = this.scale.height / 2 - 50;
    
    this.add.text(centerX, 100, 'Tap the animal to hear it!', {
      fontFamily: 'Arial, Helvetica, sans-serif',
      fontSize: '24px',
      color: '#718096'
    }).setOrigin(0.5);
    
    this.animalContainer = this.add.container(centerX, centerY);
  }

  private showAnimal(index: number): void {
    this.animalContainer.removeAll(true);
    
    const animal = this.animals[index];
    
    const bg = this.add.graphics();
    bg.fillStyle(0xffffff, 1);
    bg.fillCircle(0, 0, 120);
    bg.lineStyle(4, animal.color, 1);
    bg.strokeCircle(0, 0, 120);
    
    const animalImg = this.add.image(0, -20, animal.key).setDisplaySize(150, 150);
    
    const nameText = this.add.text(0, 80, `${animal.emoji} ${animal.name}`, {
      fontFamily: 'Arial, Helvetica, sans-serif',
      fontSize: '32px',
      fontWeight: 'bold',
      color: '#2d3748'
    }).setOrigin(0.5);
    
    const soundText = this.add.text(0, 120, animal.sound, {
      fontFamily: 'Arial, Helvetica, sans-serif',
      fontSize: '28px',
      color: '#667eea'
    }).setOrigin(0.5);
    
    this.animalContainer.add([bg, animalImg, nameText, soundText]);
    this.animalContainer.setData('animal', animal);
    
    const hitArea = new Phaser.Geom.Circle(0, 0, 120);
    this.animalContainer.setInteractive(hitArea, Phaser.Geom.Circle.Contains);
    
    this.animalContainer.on('pointerdown', () => this.onAnimalTap());
    
    this.animalContainer.setScale(0);
    this.tweens.add({
      targets: this.animalContainer,
      scale: { from: 0, to: 1 },
      duration: 400,
      ease: 'Back.out'
    });
    
    this.speakAnimal(animal);
  }

  private onAnimalTap(): void {
    if (this.isAnimating) return;
    
    this.isAnimating = true;
    const animal = this.animalContainer.getData('animal');
    
    this.playSuccessSound();
    this.showCelebration(this.animalContainer.x, this.animalContainer.y - 50);
    
    this.tweens.add({
      targets: this.animalContainer,
      scale: { from: 1, to: 1.2 },
      duration: 200,
      yoyo: true,
      onComplete: () => {
        this.speakAnimal(animal);
        
        this.time.delayedCall(1000, () => {
          this.currentIndex++;
          this.incrementProgress();
          
          if (this.currentIndex >= this.animals.length) {
            this.onGameComplete();
          } else {
            this.showAnimal(this.currentIndex);
            this.isAnimating = false;
          }
        });
      }
    });
  }

  private speakAnimal(animal: any): void {
    const utterance = new SpeechSynthesisUtterance(`${animal.name} says ${animal.sound}`);
    utterance.lang = 'en-US';
    utterance.rate = 0.7;
    utterance.pitch = 1.3;
    utterance.volume = 0.8;
    speechSynthesis.speak(utterance);
  }

  private onGameComplete(): void {
    this.playSuccessSound();
    this.showCelebration(this.scale.width / 2, this.scale.height / 2);
    
    this.time.delayedCall(1500, () => {
      this.createSpeechBubble(this.scale.width / 2, 200, 'Wow! You know all the animals! 🐄🐷🐔');
    });
    
    this.time.delayedCall(3000, () => {
      this.scene.start('MenuScene');
    });
  }
}