import { Scene, GameObjects } from 'phaser';
import { GameData } from '../utils/GameData';

export class MenuScene extends Scene {
  private games: GameData[] = [
    { key: 'counting', name: 'Counting Fun', icon: '🔢', desc: 'Tap to count 1-10', age: '1-3', color: 0xff6b6b },
    { key: 'colors', name: 'Color Match', icon: '🌈', desc: 'Find matching colors', age: '2-4', color: 0x4ecdc4 },
    { key: 'shapes', name: 'Shape Sorter', icon: '🔷', desc: 'Drag shapes to fit', age: '2-4', color: 0xffe66d },
    { key: 'animals', name: 'Animal Sounds', icon: '🐄', desc: 'Tap animals to hear them', age: '1-3', color: 0xa8e6cf },
    { key: 'balloons', name: 'Balloon Pop', icon: '🎈', desc: 'Pop and count balloons', age: '2-5', color: 0xff8b94 },
    { key: 'memory', name: 'Memory Match', icon: '🧠', desc: 'Find matching pairs', age: '3-5', color: 0xb8b8ff }
  ];

  constructor() {
    super({ key: 'MenuScene' });
  }

  create(): void {
    this.createBackground();
    this.createTitle();
    this.createGameGrid();
    this.createFooter();
  }

  private createBackground(): void {
    const graphics = this.add.graphics();
    
    const width = this.scale.width;
    const height = this.scale.height;
    
    graphics.fillGradientStyle(0x667eea, 0x667eea, 0x764ba2, 0x764ba2, 1);
    graphics.fillRect(0, 0, width, height);
    
    for (let i = 0; i < 20; i++) {
      const x = Phaser.Math.Between(0, width);
      const y = Phaser.Math.Between(0, height);
      const radius = Phaser.Math.Between(10, 60);
      const alpha = Phaser.Math.FloatBetween(0.05, 0.15);
      
      graphics.fillStyle(0xffffff, alpha);
      graphics.fillCircle(x, y, radius);
    }
    
    graphics.generateTexture('menu_bg', width, height);
    graphics.destroy();
    
    this.add.image(0, 0, 'menu_bg').setOrigin(0);
  }

  private createTitle(): void {
    const centerX = this.scale.width / 2;
    
    this.add.text(centerX, 80, '🎮 Toddler Games', {
      fontFamily: 'Arial, Helvetica, sans-serif',
      fontSize: '48px',
      fontWeight: 'bold',
      color: '#ffffff',
      stroke: '#667eea',
      strokeThickness: 4
    }).setOrigin(0.5);

    this.add.text(centerX, 140, 'Learn & Play Together', {
      fontFamily: 'Arial, Helvetica, sans-serif',
      fontSize: '24px',
      color: '#ffffff',
      alpha: 0.9
    }).setOrigin(0.5);
  }

  private createGameGrid(): void {
    const startX = 120;
    const startY = 220;
    const cardWidth = 320;
    const cardHeight = 200;
    const gapX = 40;
    const gapY = 30;
    const cols = 3;

    this.games.forEach((game, index) => {
      const col = index % cols;
      const row = Math.floor(index / cols);
      
      const x = startX + col * (cardWidth + gapX);
      const y = startY + row * (cardHeight + gapY);
      
      this.createGameCard(game, x, y, cardWidth, cardHeight, index);
    });
  }

  private createGameCard(game: GameData, x: number, y: number, width: number, height: number, index: number): void {
    const container = this.add.container(x + width/2, y + height/2);
    
    const bg = this.add.graphics();
    bg.fillStyle(0xffffff, 1);
    bg.fillRoundedRect(-width/2, -height/2, width, height, 20);
    bg.lineStyle(4, game.color, 1);
    bg.strokeRoundedRect(-width/2, -height/2, width, height, 20);
    
    const shadow = this.add.graphics();
    shadow.fillStyle(0x000000, 0.1);
    shadow.fillRoundedRect(-width/2 + 4, -height/2 + 4, width, height, 20);
    
    container.add([shadow, bg]);
    
    const icon = this.add.text(0, -50, game.icon, {
      fontSize: '64px'
    }).setOrigin(0.5);
    
    const name = this.add.text(0, 30, game.name, {
      fontFamily: 'Arial, Helvetica, sans-serif',
      fontSize: '24px',
      fontWeight: 'bold',
      color: '#2d3748'
    }).setOrigin(0.5);
    
    const desc = this.add.text(0, 65, game.desc, {
      fontFamily: 'Arial, Helvetica, sans-serif',
      fontSize: '16px',
      color: '#718096'
    }).setOrigin(0.5);
    
    const ageBadge = this.add.text(0, 100, `Ages ${game.age}`, {
      fontFamily: 'Arial, Helvetica, sans-serif',
      fontSize: '14px',
      fontWeight: 'bold',
      color: '#ffffff',
      backgroundColor: Phaser.Display.Color.IntegerToColor(game.color).rgba,
      padding: { x: 12, y: 6 }
    }).setOrigin(0.5);
    
    container.add([icon, name, desc, ageBadge]);
    
    const hitArea = new Phaser.Geom.Rectangle(-width/2, -height/2, width, height);
    
    container.setSize(width, height);
    container.setInteractive(hitArea, Phaser.Geom.Rectangle.Contains);
    
    container.on('pointerdown', () => {
      this.playClickSound();
      this.tweens.add({
        targets: container,
        scaleX: 0.95,
        scaleY: 0.95,
        duration: 100,
        yoyo: true,
        onComplete: () => {
          this.scene.start(game.key);
        }
      });
    });
    
    container.on('pointerover', () => {
      this.tweens.add({
        targets: container,
        y: container.y - 8,
        duration: 200,
        ease: 'Back.out'
      });
    });
    
    container.on('pointerout', () => {
      this.tweens.add({
        targets: container,
        y: y + height/2,
        duration: 200,
        ease: 'Back.out'
      });
    });
    
    container.setData('originalY', y + height/2);
    
    this.tweens.add({
      targets: container,
      alpha: { from: 0, to: 1 },
      y: { from: y + height/2 + 50, to: y + height/2 },
      duration: 500,
      delay: index * 100,
      ease: 'Back.out'
    });
  }

  private createFooter(): void {
    const centerX = this.scale.width / 2;
    const bottomY = this.scale.height - 40;
    
    this.add.text(centerX, bottomY, 'Made with ❤️ for little learners', {
      fontFamily: 'Arial, Helvetica, sans-serif',
      fontSize: '16px',
      color: '#ffffff',
      alpha: 0.8
    }).setOrigin(0.5);
  }

  private playClickSound(): void {
    this.sound.play('click', { volume: 0.3 });
  }
}