import { Scene } from 'phaser';

export class BootScene extends Scene {
  constructor() {
    super({ key: 'BootScene' });
  }

  preload(): void {
    this.load.setPath('assets/');
    
    this.load.audio('pop', 'sounds/pop.mp3');
    this.load.audio('success', 'sounds/success.mp3');
    this.load.audio('click', 'sounds/click.mp3');
    this.load.audio('wrong', 'sounds/wrong.mp3');
    
    // Create placeholder graphics programmatically
    this.createPlaceholderAssets();
  }

  create(): void {
    this.scene.start('MenuScene');
  }

  private createPlaceholderAssets(): void {
    const graphics = this.add.graphics();
    
    const shapes = [
      { key: 'circle', color: 0xff6b6b },
      { key: 'square', color: 0x4ecdc4 },
      { key: 'triangle', color: 0xffe66d },
      { key: 'star', color: 0xa8e6cf },
      { key: 'heart', color: 0xff8b94 },
      { key: 'diamond', color: 0xb8b8ff }
    ];

    shapes.forEach(({ key, color }) => {
      graphics.clear();
      graphics.fillStyle(color, 1);
      
      switch (key) {
        case 'circle':
          graphics.fillCircle(64, 64, 50);
          break;
        case 'square':
          graphics.fillRect(14, 14, 100, 100);
          break;
        case 'triangle':
          graphics.fillTriangle(64, 14, 14, 114, 114, 114);
          break;
        case 'star':
          this.drawStar(graphics, 64, 64, 5, 50, 25);
          break;
        case 'heart':
          this.drawHeart(graphics, 64, 50, 50);
          break;
        case 'diamond':
          graphics.fillRoundedRect(14, 14, 100, 100, 8);
          graphics.rotation = Phaser.Math.DegToRad(45);
          break;
      }
      
      graphics.generateTexture(key, 128, 128);
    });

    const animals = [
      { key: 'cow', color: 0x8b4513, sound: 'moo' },
      { key: 'pig', color: 0xffb6c1, sound: 'oink' },
      { key: 'chicken', color: 0xffd700, sound: 'cluck' },
      { key: 'sheep', color: 0xf5f5dc, sound: 'baa' },
      { key: 'horse', color: 0x8b4513, sound: 'neigh' },
      { key: 'duck', color: 0xffff00, sound: 'quack' }
    ];

    animals.forEach(({ key, color }) => {
      graphics.clear();
      graphics.fillStyle(color, 1);
      graphics.fillCircle(64, 64, 50);
      graphics.fillStyle(0x000000, 1);
      graphics.fillCircle(44, 54, 8);
      graphics.fillCircle(84, 54, 8);
      graphics.generateTexture(key, 128, 128);
    });

    // Balloon
    graphics.clear();
    graphics.fillStyle(0xff6b6b, 1);
    graphics.fillEllipse(64, 70, 50, 70);
    graphics.fillStyle(0xffffff, 0.3);
    graphics.fillEllipse(50, 55, 15, 10);
    graphics.generateTexture('balloon_red', 128, 128);
    
    graphics.clear();
    graphics.fillStyle(0x4ecdc4, 1);
    graphics.fillEllipse(64, 70, 50, 70);
    graphics.fillStyle(0xffffff, 0.3);
    graphics.fillEllipse(50, 55, 15, 10);
    graphics.generateTexture('balloon_blue', 128, 128);
    
    graphics.clear();
    graphics.fillStyle(0xffe66d, 1);
    graphics.fillEllipse(64, 70, 50, 70);
    graphics.fillStyle(0xffffff, 0.3);
    graphics.fillEllipse(50, 55, 15, 10);
    graphics.generateTexture('balloon_yellow', 128, 128);
    
    graphics.clear();
    graphics.fillStyle(0xa8e6cf, 1);
    graphics.fillEllipse(64, 70, 50, 70);
    graphics.fillStyle(0xffffff, 0.3);
    graphics.fillEllipse(50, 55, 15, 10);
    graphics.generateTexture('balloon_green', 128, 128);

    graphics.destroy();
  }

  private drawStar(graphics: Phaser.GameObjects.Graphics, cx: number, cy: number, spikes: number, outerRadius: number, innerRadius: number): void {
    let rot = Phaser.Math.DegToRad(90 - 360 / spikes / 2);
    let x = cx;
    let y = cy;
    let step = Phaser.Math.DegToRad(360 / spikes);
    
    graphics.beginPath();
    graphics.moveTo(cx, cy - outerRadius);
    
    for (let i = 0; i < spikes; i++) {
      x = cx + Math.cos(rot) * outerRadius;
      y = cy + Math.sin(rot) * outerRadius;
      graphics.lineTo(x, y);
      rot += step;
      
      x = cx + Math.cos(rot) * innerRadius;
      y = cy + Math.sin(rot) * innerRadius;
      graphics.lineTo(x, y);
      rot += step;
    }
    
    graphics.closePath();
    graphics.fillPath();
  }

  private drawHeart(graphics: Phaser.GameObjects.Graphics, cx: number, cy: number, size: number): void {
    graphics.beginPath();
    graphics.moveTo(cx, cy + size * 0.3);
    
    graphics.bezierCurveTo(
      cx, cy - size * 0.2,
      cx - size, cy - size * 0.5,
      cx - size, cy + size * 0.2
    );
    
    graphics.bezierCurveTo(
      cx - size, cy + size * 0.6,
      cx, cy + size,
      cx, cy + size
    );
    
    graphics.bezierCurveTo(
      cx, cy + size,
      cx + size, cy + size * 0.6,
      cx + size, cy + size * 0.2
    );
    
    graphics.bezierCurveTo(
      cx + size, cy - size * 0.5,
      cx, cy - size * 0.2,
      cx, cy + size * 0.3
    );
    
    graphics.closePath();
    graphics.fillPath();
  }
}