import { BaseGameScene } from './BaseGameScene';
import { GameObjects } from 'phaser';

export class BalloonsScene extends BaseGameScene {
  private balloons: GameObjects.Container[] = [];
  private balloonColors = ['balloon_red', 'balloon_blue', 'balloon_yellow', 'balloon_green'];
  private balloonsToPop: number = 15;
  private poppedCount: number = 0;
  private spawnTimer?: Phaser.Time.TimerEvent;
  private maxBalloonsOnScreen: number = 8;

  constructor() {
    super({ key: 'BalloonsScene' });
  }

  create(): void {
    super.create();
    this.totalSteps = this.balloonsToPop;
    this.createInstructions();
    this.startSpawning();
  }

  private createInstructions(): void {
    const centerX = this.scale.width / 2;
    
    this.add.text(centerX, 100, 'Pop the balloons!', {
      fontFamily: 'Arial, Helvetica, sans-serif',
      fontSize: '28px',
      fontWeight: 'bold',
      color: '#667eea'
    }).setOrigin(0.5);
    
    this.add.text(centerX, 140, `Pop ${this.balloonsToPop} balloons`, {
      fontFamily: 'Arial, Helvetica, sans-serif',
      fontSize: '20px',
      color: '#718096'
    }).setOrigin(0.5);
  }

  private startSpawning(): void {
    this.spawnBalloon();
    this.spawnTimer = this.time.addEvent({
      delay: Phaser.Math.Between(800, 1500),
      callback: this.spawnBalloon,
      callbackScope: this,
      loop: true
    });
  }

  private spawnBalloon(): void {
    if (this.balloons.length >= this.maxBalloonsOnScreen || this.poppedCount >= this.balloonsToPop) {
      return;
    }
    
    const balloonType = Phaser.Utils.Array.GetRandom(this.balloonColors);
    const startX = Phaser.Math.Between(100, this.scale.width - 100);
    const startY = this.scale.height + 100;
    
    const container = this.add.container(startX, startY);
    
    const balloon = this.add.image(0, 0, balloonType).setDisplaySize(70, 100);
    
    const string = this.add.graphics();
    string.lineStyle(2, 0x666666, 1);
    string.beginPath();
    string.moveTo(0, 50);
    string.lineTo(0, 80);
    string.strokePath();
    
    const number = this.poppedCount + this.balloons.length + 1;
    const numberText = this.add.text(0, 10, number.toString(), {
      fontFamily: 'Arial, Helvetica, sans-serif',
      fontSize: '24px',
      fontWeight: 'bold',
      color: '#ffffff',
      stroke: '#000000',
      strokeThickness: 3
    }).setOrigin(0.5);
    
    container.add([string, balloon, numberText]);
    container.setData('popped', false);
    
    const hitArea = new Phaser.Geom.Rectangle(-35, -50, 70, 100);
    container.setInteractive(hitArea, Phaser.Geom.Rectangle.Contains);
    
    container.on('pointerdown', () => this.onBalloonTap(container));
    
    this.balloons.push(container);
    
    const duration = Phaser.Math.Between(8000, 12000);
    this.tweens.add({
      targets: container,
      y: -150,
      duration: duration,
      ease: 'Sine.inOut',
      onComplete: () => {
        if (!container.getData('popped')) {
          this.onBalloonEscape(container);
        }
      }
    });
    
    container.setScale(0.5);
    this.tweens.add({
      targets: container,
      scale: 1,
      duration: 300,
      ease: 'Back.out'
    });
  }

  private onBalloonTap(container: GameObjects.Container): void {
    if (container.getData('popped')) return;
    
    container.setData('popped', true);
    this.poppedCount++;
    this.incrementProgress();
    
    this.playPopSound();
    this.showCelebration(container.x, container.y);
    this.speakNumber(this.poppedCount);
    
    this.tweens.add({
      targets: container,
      scale: { from: 1, to: 2 },
      alpha: { from: 1, to: 0 },
      duration: 300,
      onComplete: () => {
        this.removeBalloon(container);
        
        if (this.poppedCount >= this.balloonsToPop) {
          this.onGameComplete();
        }
      }
    });
  }

  private onBalloonEscape(container: GameObjects.Container): void {
    this.removeBalloon(container);
  }

  private removeBalloon(container: GameObjects.Container): void {
    const index = this.balloons.indexOf(container);
    if (index > -1) {
      this.balloons.splice(index, 1);
    }
    container.destroy();
  }

  private speakNumber(num: number): void {
    const utterance = new SpeechSynthesisUtterance(num.toString());
    utterance.lang = 'en-US';
    utterance.rate = 0.9;
    utterance.pitch = 1.2;
    utterance.volume = 0.7;
    speechSynthesis.speak(utterance);
  }

  private onGameComplete(): void {
    if (this.spawnTimer) {
      this.spawnTimer.remove();
    }
    
    this.balloons.forEach(b => {
      b.disableInteractive();
      this.tweens.add({
        targets: b,
        alpha: 0,
        duration: 500
      });
    });
    
    this.playSuccessSound();
    this.showCelebration(this.scale.width / 2, this.scale.height / 2);
    
    this.time.delayedCall(1500, () => {
      this.createSpeechBubble(this.scale.width / 2, 200, `Fantastic! You popped ${this.balloonsToPop} balloons! 🎈`);
    });
    
    this.time.delayedCall(3000, () => {
      this.scene.start('MenuScene');
    });
  }
}