import { BaseGameScene } from './BaseGameScene';
import { GameObjects, Input } from 'phaser';

export class CountingScene extends BaseGameScene {
  private currentNumber: number = 1;
  private maxNumber: number = 10;
  private numberDisplay!: GameObjects.Text;
  private items: GameObjects.GameObject[] = [];
  private itemContainer!: GameObjects.Container;
  private isAnimating: boolean = false;

  constructor() {
    super({ key: 'CountingScene' });
  }

  create(): void {
    super.create();
    this.totalSteps = this.maxNumber;
    this.createNumberDisplay();
    this.createItemArea();
    this.spawnItems(this.currentNumber);
    this.speakNumber(this.currentNumber);
  }

  private createNumberDisplay(): void {
    const centerX = this.scale.width / 2;
    
    this.numberDisplay = this.add.text(centerX, 150, '', {
      fontFamily: 'Arial, Helvetica, sans-serif',
      fontSize: '120px',
      fontWeight: 'bold',
      color: '#667eea',
      stroke: '#ffffff',
      strokeThickness: 8
    }).setOrigin(0.5);
    
    this.add.text(centerX, 250, 'Tap each item to count!', {
      fontFamily: 'Arial, Helvetica, sans-serif',
      fontSize: '20px',
      color: '#718096'
    }).setOrigin(0.5);
  }

  private createItemArea(): void {
    this.itemContainer = this.add.container(this.scale.width / 2, this.scale.height / 2 + 50);
  }

  private spawnItems(count: number): void {
    this.clearItems();
    
    const cols = Math.min(count, 5);
    const rows = Math.ceil(count / 5);
    const spacing = 100;
    const startX = -(cols - 1) * spacing / 2;
    const startY = -(rows - 1) * spacing / 2;
    
    for (let i = 0; i < count; i++) {
      const col = i % cols;
      const row = Math.floor(i / cols);
      
      const x = startX + col * spacing;
      const y = startY + row * spacing;
      
      this.createItem(x, y, i + 1);
    }
  }

  private createItem(x: number, y: number, index: number): void {
    const colors = [0xff6b6b, 0x4ecdc4, 0xffe66d, 0xa8e6cf, 0xff8b94, 0xb8b8ff];
    const color = Phaser.Utils.Array.GetRandom(colors);
    const shapes = ['circle', 'square', 'triangle', 'star', 'heart', 'diamond'];
    const shape = Phaser.Utils.Array.GetRandom(shapes);
    
    const container = this.add.container(x, y);
    
    const shapeObj = this.add.image(0, 0, shape).setDisplaySize(80, 80).setTint(color);
    
    const numberLabel = this.add.text(0, 0, index.toString(), {
      fontFamily: 'Arial, Helvetica, sans-serif',
      fontSize: '28px',
      fontWeight: 'bold',
      color: '#ffffff',
      stroke: '#000000',
      strokeThickness: 4
    }).setOrigin(0.5);
    
    container.add([shapeObj, numberLabel]);
    container.setData('index', index);
    container.setData('counted', false);
    
    const hitArea = new Phaser.Geom.Circle(0, 0, 50);
    container.setInteractive(hitArea, Phaser.Geom.Circle.Contains);
    
    container.on('pointerdown', () => this.onItemTap(container));
    
    this.itemContainer.add(container);
    this.items.push(container);
    
    container.setScale(0);
    this.tweens.add({
      targets: container,
      scale: { from: 0, to: 1 },
      duration: 300,
      delay: index * 80,
      ease: 'Back.out'
    });
  }

  private onItemTap(item: GameObjects.Container): void {
    if (this.isAnimating || item.getData('counted')) return;
    
    const index = item.getData('index');
    
    if (index === this.currentNumber) {
      item.setData('counted', true);
      this.isAnimating = true;
      
      this.playPopSound();
      this.showCelebration(item.x + this.itemContainer.x, item.y + this.itemContainer.y);
      this.speakNumber(index);
      
      this.tweens.add({
        targets: item,
        scale: { from: 1, to: 1.3 },
        rotation: { from: 0, to: Math.PI * 2 },
        duration: 400,
        ease: 'Back.out',
        onComplete: () => {
          this.tweens.add({
            targets: item,
            alpha: { from: 1, to: 0 },
            scale: { from: 1.3, to: 0 },
            duration: 300,
            onComplete: () => {
              this.currentNumber++;
              this.incrementProgress();
              this.numberDisplay.setText(this.currentNumber.toString());
              
              if (this.currentNumber > this.maxNumber) {
                this.onGameComplete();
              } else {
                setTimeout(() => {
                  this.speakNumber(this.currentNumber);
                  this.isAnimating = false;
                }, 500);
              }
            }
          });
        }
      });
    } else {
      this.playWrongSound();
      this.tweens.add({
        targets: item,
        x: { from: item.x, to: item.x - 20 },
        yoyo: true,
        repeat: 3,
        duration: 80
      });
    }
  }

  private speakNumber(num: number): void {
    const utterance = new SpeechSynthesisUtterance(num.toString());
    utterance.lang = 'en-US';
    utterance.rate = 0.8;
    utterance.pitch = 1.2;
    utterance.volume = 0.8;
    speechSynthesis.speak(utterance);
  }

  private onGameComplete(): void {
    this.playSuccessSound();
    this.showCelebration(this.scale.width / 2, this.scale.height / 2);
    
    this.time.delayedCall(1500, () => {
      this.createSpeechBubble(this.scale.width / 2, 200, 'Great job! You counted to 10! 🎉');
    });
    
    this.time.delayedCall(3000, () => {
      this.scene.start('MenuScene');
    });
  }

  private clearItems(): void {
    this.items.forEach(item => item.destroy());
    this.items = [];
  }
}