import { BaseGameScene } from './BaseGameScene';
import { GameObjects } from 'phaser';

export class ShapesScene extends BaseGameScene {
  private shapes = [
    { key: 'circle', name: 'Circle', emoji: '⭕' },
    { key: 'square', name: 'Square', emoji: '⬜' },
    { key: 'triangle', name: 'Triangle', emoji: '🔺' },
    { key: 'star', name: 'Star', emoji: '⭐' },
    { key: 'heart', name: 'Heart', emoji: '❤️' },
    { key: 'diamond', name: 'Diamond', emoji: '💎' }
  ];
  
  private slots: { x: number; y: number; shapeKey: string; filled: boolean; shapeObj?: GameObjects.Image }[] = [];
  private draggables: GameObjects.Container[] = [];
  private isAnimating: boolean = false;
  private completedCount: number = 0;

  constructor() {
    super({ key: 'ShapesScene' });
  }

  create(): void {
    super.create();
    this.totalSteps = this.shapes.length;
    this.createSlots();
    this.createDraggables();
    this.updateProgressBar();
  }

  private createSlots(): void {
    const centerX = this.scale.width / 2;
    const centerY = this.scale.height / 2 - 20;
    
    this.add.text(centerX, 100, 'Drag shapes to match!', {
      fontFamily: 'Arial, Helvetica, sans-serif',
      fontSize: '24px',
      color: '#718096'
    }).setOrigin(0.5);
    
    const cols = 3;
    const rows = 2;
    const spacing = 140;
    const startX = centerX - (cols - 1) * spacing / 2;
    const startY = centerY - (rows - 1) * spacing / 2;
    
    this.shapes.forEach((shape, index) => {
      const col = index % cols;
      const row = Math.floor(index / cols);
      const x = startX + col * spacing;
      const y = startY + row * spacing;
      
      const slotBg = this.add.graphics();
      slotBg.fillStyle(0xffffff, 1);
      slotBg.lineStyle(3, 0xe2e8f0, 1);
      slotBg.strokeRoundedRect(x - 60, y - 60, 120, 120, 20);
      slotBg.fillStyle(0xf7fafc, 1);
      slotBg.fillRoundedRect(x - 58, y - 58, 116, 116, 18);
      
      const shapeOutline = this.add.image(x, y, shape.key).setDisplaySize(80, 80).setTint(0xcbd5e0).setAlpha(0.5);
      
      this.slots.push({ x, y, shapeKey: shape.key, filled: false });
    });
  }

  private createDraggables(): void {
    const centerX = this.scale.width / 2;
    const bottomY = this.scale.height - 120;
    
    const availableShapes = [...this.shapes];
    for (let i = availableShapes.length - 1; i > 0; i--) {
      const j = Phaser.Math.Between(0, i);
      [availableShapes[i], availableShapes[j]] = [availableShapes[j], availableShapes[i]];
    }
    
    const spacing = 130;
    const startX = centerX - (availableShapes.length - 1) * spacing / 2;
    
    availableShapes.forEach((shape, index) => {
      const x = startX + index * spacing;
      const y = bottomY;
      
      const container = this.add.container(x, y);
      
      const shapeObj = this.add.image(0, 0, shape.key).setDisplaySize(80, 80).setTint(0x667eea);
      
      const glow = this.add.graphics();
      glow.fillStyle(0x667eea, 0.3);
      glow.fillCircle(0, 0, 50);
      
      container.add([glow, shapeObj]);
      container.setData('shapeKey', shape.key);
      container.setData('originalX', x);
      container.setData('originalY', y);
      
      this.input.setDraggable(container);
      
      container.on('dragstart', () => {
        this.playClickSound();
        this.tweens.add({
          targets: container,
          scale: 1.2,
          duration: 200
        });
        this.children.bringToTop(container);
      });
      
      container.on('drag', (pointer: Phaser.Input.Pointer, dragX: number, dragY: number) => {
        container.x = dragX;
        container.y = dragY;
      });
      
      container.on('dragend', () => {
        this.onDragEnd(container);
      });
      
      this.draggables.push(container);
      
      container.setScale(0);
      this.tweens.add({
        targets: container,
        scale: { from: 0, to: 1 },
        duration: 400,
        delay: index * 100,
        ease: 'Back.out'
      });
    });
  }

  private onDragEnd(container: GameObjects.Container): void {
    if (this.isAnimating) return;
    
    const shapeKey = container.getData('shapeKey');
    let matchedSlot = null;
    let minDistance = Infinity;
    
    this.slots.forEach((slot, index) => {
      if (!slot.filled) {
        const distance = Phaser.Math.Distance.Between(
          container.x, container.y,
          slot.x, slot.y
        );
        if (distance < 80 && distance < minDistance) {
          minDistance = distance;
          matchedSlot = { slot, index };
        }
      }
    });
    
    if (matchedSlot && matchedSlot.slot.shapeKey === shapeKey) {
      this.onCorrectMatch(container, matchedSlot.slot, matchedSlot.index);
    } else {
      this.onWrongMatch(container);
    }
  }

  private onCorrectMatch(container: GameObjects.Container, slot: any, slotIndex: number): void {
    this.isAnimating = true;
    this.playSuccessSound();
    this.showCelebration(slot.x, slot.y);
    
    slot.filled = true;
    this.completedCount++;
    this.incrementProgress();
    
    this.tweens.add({
      targets: container,
      x: slot.x,
      y: slot.y,
      scale: { from: 1.2, to: 1 },
      duration: 400,
      ease: 'Back.out',
      onComplete: () => {
        container.disableInteractive();
        container.removeAllListeners('drag');
        container.removeAllListeners('dragstart');
        container.removeAllListeners('dragend');
        
        if (this.completedCount >= this.shapes.length) {
          this.onGameComplete();
        } else {
          this.isAnimating = false;
        }
      }
    });
  }

  private onWrongMatch(container: GameObjects.Container): void {
    this.playWrongSound();
    const origX = container.getData('originalX');
    const origY = container.getData('originalY');
    
    this.tweens.add({
      targets: container,
      x: origX,
      y: origY,
      scale: 1,
      duration: 400,
      ease: 'Back.out'
    });
    
    this.tweens.add({
      targets: container,
      x: { from: origX, to: origX - 20 },
      yoyo: true,
      repeat: 3,
      duration: 80
    });
  }

  private onGameComplete(): void {
    this.playSuccessSound();
    this.showCelebration(this.scale.width / 2, this.scale.height / 2);
    
    this.time.delayedCall(1500, () => {
      this.createSpeechBubble(this.scale.width / 2, 200, 'Perfect! All shapes match! 🎉');
    });
    
    this.time.delayedCall(3000, () => {
      this.scene.start('MenuScene');
    });
  }
}